//! Export installed packages as a Scoop-compatible JSON document.
//!
//! Emits the same shape as upstream `scoop export`
//! (`libexec/scoop-export.ps1` + `libexec/scoop-list.ps1:24-63` +
//! `lib/buckets.ps1:104-121`), so the document can be fed to `scoop import`:
//!
//! ```json
//! {
//!   "buckets": [ { "Name": "main", "Source": "https://…/Main", "Updated": "…", "Manifests": 1300 } ],
//!   "apps":    [ { "Name": "7zip", "Version": "26.03", "Source": "main", "Updated": "…", "Info": "" } ]
//! }
//! ```
//!
//! `apps[].Source` follows upstream: the origin bucket name, `<auto-generated>`
//! for a generated user manifest, otherwise the manifest URL / local path
//! (URL/path installs carry no bucket). `apps[].Info` is upstream's fixed word
//! list — `Deprecated package`, `Global install`, `Install failed`,
//! `Held package`, then the architecture when it differs from the default.
//! Timestamps are written in upstream's `.NET` round-trip shape
//! (`2026-09-04T20:06:02.386467+08:00`), so a consumer parses the same type
//! `scoop export` produces.
//!
//! # hok extension
//!
//! With the `hok` flag a Scoop-ignored extension is appended, carrying what
//! upstream expresses only inside the `Info` string: a top-level `hok`
//! namespace holding hok's own config verbatim, and a per-app `Hok` object
//! (`Hold` / `Global` / `Architecture` / `Failed`). Upstream's importer reads
//! only `config` / `buckets` / `apps` and the five documented app fields, so
//! both variants are valid Scoopfiles — and the extension makes an hok → hok
//! round trip lossless without parsing human-readable words back.

use std::path::{Path, PathBuf};

use serde_json::{Map, Value};

use crate::constant::{
    AUTO_GENERATED_SOURCE, INFO_DEPRECATED, INFO_FAILED, INFO_GLOBAL, INFO_HELD,
    ISOLATED_PACKAGE_BUCKET,
};
use crate::error::Fallible;
use crate::internal::{arch::Arch, git, time as internal_time};
use crate::package::query::query_installed;
use crate::package::source::{SourceState, classify};
use crate::package::{Package, QueryOption};
use crate::{Session, bucket};

/// Build the export document for every installed package.
///
/// Both scopes are exported (local and global, mirroring upstream
/// `scoop-list.ps1:15-18`) and partial/broken installs are exported too (as
/// `Install failed`) instead of being dropped.
///
/// # Errors
///
/// Returns an error if listing buckets or querying installed packages fails.
pub fn build_export(session: &Session, hok: bool) -> Fallible<Value> {
    let mut output = Map::new();
    // The Scoop-compatible part comes first, in upstream's order.
    output.insert("buckets".to_owned(), Value::Array(buckets(session)?));
    output.insert("apps".to_owned(), Value::Array(apps(session, hok)?));
    if hok {
        output.insert("hok".to_owned(), hok_section(session)?);
    }
    Ok(Value::Object(output))
}

/// `buckets` — upstream `list_buckets` (`lib/buckets.ps1:104-121`).
fn buckets(session: &Session) -> Fallible<Vec<Value>> {
    let buckets = bucket::list(session)?;
    Ok(buckets
        .iter()
        .map(|bucket| {
            let mut item = Map::new();
            item.insert("Name".to_owned(), Value::String(bucket.name().to_owned()));
            // `Bucket::source` is the git remote when there is one, otherwise
            // the local path — the same pair upstream picks.
            item.insert(
                "Source".to_owned(),
                Value::String(bucket.source().to_owned()),
            );
            // Upstream uses the HEAD commit date for git buckets and the
            // manifest directory's timestamp otherwise.
            let updated = git::head_commit_time(bucket.path())
                .and_then(seconds_string)
                .or_else(|| mtime_string(&manifest_dir(bucket.path())));
            item.insert("Updated".to_owned(), updated.into());
            item.insert("Manifests".to_owned(), Value::from(bucket.manifest_count()));
            Value::Object(item)
        })
        .collect())
}

/// The directory upstream timestamps for a bucket without git metadata:
/// `<path>\bucket` when the categorized layout is in use, the root otherwise.
fn manifest_dir(bucket_path: &Path) -> PathBuf {
    let categorized = bucket_path.join("bucket");
    if categorized.is_dir() {
        categorized
    } else {
        bucket_path.to_path_buf()
    }
}

/// `apps` — upstream `scoop-list.ps1:24-63`, local scope then global.
fn apps(session: &Session, hok: bool) -> Fallible<Vec<Value>> {
    let original_global = session.is_global();
    let mut out = Vec::new();
    let mut failure = None;
    for global in [false, true] {
        session.set_global(global);
        // `Broken` so partial installs are exported (as `Install failed`)
        // instead of disappearing from the Scoopfile.
        let packages = match query_installed(session, &["*"], &[QueryOption::Broken]) {
            Ok(packages) => packages,
            Err(e) => {
                failure = Some(e);
                break;
            }
        };
        let sources = classify(session, &packages);
        for (package, source) in packages.iter().zip(sources) {
            out.push(app_entry(session, package, source, global, hok));
        }
    }
    // Restore the scope before propagating: a failed export must not leave the
    // session pointing at the global root.
    session.set_global(original_global);
    match failure {
        Some(e) => Err(e),
        None => Ok(out),
    }
}

/// One `apps[]` entry.
fn app_entry(
    session: &Session,
    package: &Package,
    source: SourceState,
    global: bool,
    hok: bool,
) -> Value {
    let mut item = Map::new();
    item.insert("Name".to_owned(), Value::String(package.name().to_owned()));
    // An unresolvable version is `null` upstream; the query layer reports an
    // empty string for a broken install, so normalize it here.
    item.insert(
        "Version".to_owned(),
        package
            .installed_version()
            .filter(|version| !version.is_empty())
            .map(str::to_owned)
            .into(),
    );
    item.insert("Source".to_owned(), source_value(session, package));
    item.insert("Updated".to_owned(), app_updated(session, package).into());
    item.insert(
        "Info".to_owned(),
        Value::String(info_string(package, source, global)),
    );
    if hok {
        item.insert("Hok".to_owned(), hok_app_state(package, global));
    }
    Value::Object(item)
}

/// `apps[].Source` — bucket name, `<auto-generated>`, the manifest URL/path,
/// or null, in upstream's precedence (`libexec/scoop-list.ps1:42-47`).
fn source_value(session: &Session, package: &Package) -> Value {
    if let Some(bucket) = package.installed_bucket()
        && bucket != ISOLATED_PACKAGE_BUCKET
    {
        return Value::String(bucket.to_owned());
    }
    match package.installed_url() {
        Some(url) if same_path(url, &user_manifest(session, package.name())) => {
            Value::String(AUTO_GENERATED_SOURCE.to_owned())
        }
        Some(url) => Value::String(url.to_owned()),
        None => Value::Null,
    }
}

/// The generated user manifest of an app (`<root>/workspace/<name>.json`,
/// upstream `usermanifest`).
fn user_manifest(session: &Session, name: &str) -> PathBuf {
    session.workspace_dir().join(format!("{name}.json"))
}

/// Whether a recorded install URL is the app's generated user manifest.
///
/// Upstream compares with PowerShell `-eq` (case-insensitive), and the
/// separators may differ between the writer and this reader.
fn same_path(url: &str, path: &Path) -> bool {
    let url = url.replace('/', "\\");
    let path = path.display().to_string().replace('/', "\\");
    url.eq_ignore_ascii_case(&path)
}

/// `apps[].Updated` — the `install.json` timestamp when there is one, else the
/// app directory's, as upstream does (`libexec/scoop-list.ps1:35-40`).
fn app_updated(session: &Session, package: &Package) -> Option<String> {
    session
        .app_current_dir(package.name())
        .and_then(|dir| mtime_string(&dir.join("install.json")))
        .or_else(|| mtime_string(&session.app_dir(package.name())))
}

/// `apps[].Info` — upstream's fixed word list, in upstream's order.
fn info_string(package: &Package, source: SourceState, global: bool) -> String {
    let mut info = Vec::new();
    if source == SourceState::Deprecated {
        info.push(INFO_DEPRECATED);
    }
    if global {
        info.push(INFO_GLOBAL);
    }
    if package.is_install_failed() {
        info.push(INFO_FAILED);
    }
    if package.is_held() {
        info.push(INFO_HELD);
    }
    if let Some(arch) = package.installed_arch()
        && !arch.eq_ignore_ascii_case(Arch::current().name())
    {
        info.push(arch);
    }
    info.join(", ")
}

/// The per-app `Hok` extension: the state hok restores verbatim on import,
/// instead of re-parsing the human-readable `Info` words. The install source
/// needs no extra field — `Source` already carries it.
fn hok_app_state(package: &Package, global: bool) -> Value {
    let mut extra = Map::new();
    extra.insert("Hold".to_owned(), Value::Bool(package.is_held()));
    extra.insert("Global".to_owned(), Value::Bool(global));
    extra.insert(
        "Architecture".to_owned(),
        package.installed_arch().map(str::to_owned).into(),
    );
    extra.insert(
        "Failed".to_owned(),
        Value::Bool(package.is_install_failed()),
    );
    Value::Object(extra)
}

/// The `hok` extension namespace: hok's own config, verbatim.
///
/// Kept whole (including absolute paths) on purpose: this section exists for
/// an hok → hok round trip, and upstream ignores the key entirely.
fn hok_section(session: &Session) -> Fallible<Value> {
    let mut section = Map::new();
    section.insert("version".to_owned(), Value::from(1));
    // `config::list` is the crate's own serialization of the whole config.
    section.insert(
        "config".to_owned(),
        serde_json::from_str(&crate::config::list(session)?)?,
    );
    Ok(Value::Object(section))
}

/// A path's last-modification time in upstream's timestamp shape, or `None`
/// when the path is missing or its time is unreadable.
fn mtime_string(path: &Path) -> Option<String> {
    let duration = std::fs::metadata(path)
        .ok()?
        .modified()
        .ok()?
        .duration_since(std::time::UNIX_EPOCH)
        .ok()?;
    let timestamp = time::OffsetDateTime::from_unix_timestamp(duration.as_secs() as i64).ok()?;
    let timestamp = timestamp.replace_nanosecond(duration.subsec_nanos()).ok()?;
    Some(internal_time::format_last_update(timestamp))
}

/// Unix seconds in upstream's timestamp shape (a bucket's HEAD commit date).
fn seconds_string(secs: i64) -> Option<String> {
    let timestamp = time::OffsetDateTime::from_unix_timestamp(secs).ok()?;
    Some(internal_time::format_last_update(timestamp))
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::test_utils::{mark_installed, test_session, tmpdir, write_bucket_manifest};

    const MANIFEST: &str =
        r#"{"version": "1.0.0", "homepage": "https://example.com", "license": "MIT"}"#;

    /// Mark an app installed from a manifest URL / local path (`install.json`
    /// carries `url` instead of `bucket`).
    fn mark_isolated(root: &Path, name: &str, url: &str) {
        let current = root.join("apps").join(name).join("current");
        std::fs::create_dir_all(&current).unwrap();
        std::fs::write(current.join("manifest.json"), MANIFEST).unwrap();
        std::fs::write(
            current.join("install.json"),
            serde_json::json!({ "architecture": "64bit", "url": url }).to_string(),
        )
        .unwrap();
    }

    fn entry_for<'a>(document: &'a Value, name: &str) -> &'a Value {
        document["apps"]
            .as_array()
            .expect("apps is an array")
            .iter()
            .find(|app| app["Name"] == name)
            .unwrap_or_else(|| panic!("no entry for {name}: {document}"))
    }

    /// The document is upstream's shape: both top-level keys are arrays, and a
    /// bucket-installed app carries the five documented fields.
    #[test]
    fn export_uses_upstream_shape() {
        let root = tmpdir("export_shape");
        let session = test_session(&root);
        write_bucket_manifest(&root, "main", "app", MANIFEST);
        mark_installed(&root, "app", "main", MANIFEST, false);

        let doc = build_export(&session, false).unwrap();
        assert!(doc["buckets"].is_array(), "buckets must be an array");
        assert!(doc["apps"].is_array(), "apps must be an array");
        assert!(doc.get("hok").is_none(), "no extension without the flag");

        let app = entry_for(&doc, "app");
        assert_eq!(app["Version"], "1.0.0");
        assert_eq!(app["Source"], "main");
        assert_eq!(app["Info"], "");
        assert!(app.get("Hok").is_none(), "extension is opt-in per app");

        let bucket = &doc["buckets"][0];
        assert_eq!(bucket["Name"], "main");
        assert!(bucket["Source"].is_string());
        assert!(bucket["Manifests"].is_u64());

        let _ = std::fs::remove_dir_all(&root);
    }

    /// The `hok` flag adds the namespace and the per-app object, and an install
    /// held with a non-default architecture reports both upstream words.
    #[test]
    fn hok_extension_carries_explicit_state() {
        let root = tmpdir("export_hok_extension");
        let session = test_session(&root);
        let manifest =
            r#"{"version": "2.0.0", "homepage": "https://example.com", "license": "MIT"}"#;
        write_bucket_manifest(&root, "extras", "held", manifest);
        mark_installed(&root, "held", "extras", manifest, false);
        std::fs::write(
            root.join("apps/held/current/install.json"),
            r#"{"architecture": "32bit", "bucket": "extras", "hold": true}"#,
        )
        .unwrap();

        let doc = build_export(&session, true).unwrap();
        let app = entry_for(&doc, "held");
        assert_eq!(app["Info"], "Held package, 32bit");
        assert_eq!(app["Hok"]["Hold"], true);
        assert_eq!(app["Hok"]["Architecture"], "32bit");
        assert_eq!(app["Hok"]["Failed"], false);
        assert_eq!(app["Hok"]["Global"], false);
        assert_eq!(doc["hok"]["version"], 1);
        assert!(doc["hok"]["config"].is_object());

        let _ = std::fs::remove_dir_all(&root);
    }

    /// A partial install is exported (as `Install failed`) rather than dropped,
    /// matching upstream's unconditional listing.
    #[test]
    fn broken_install_is_exported_as_failed() {
        let root = tmpdir("export_broken");
        let session = test_session(&root);
        // An app directory with no version to resolve: a failed install.
        std::fs::create_dir_all(root.join("apps/broken")).unwrap();

        let doc = build_export(&session, false).unwrap();
        let app = entry_for(&doc, "broken");
        assert_eq!(app["Info"], "Install failed");
        assert!(app["Version"].is_null());
        assert!(app["Source"].is_null());

        let _ = std::fs::remove_dir_all(&root);
    }

    /// A URL-installed app is sourced by its manifest URL, and a generated user
    /// manifest by upstream's `<auto-generated>` marker.
    #[test]
    fn isolated_install_source_follows_upstream() {
        let root = tmpdir("export_isolated");
        let session = test_session(&root);
        mark_isolated(&root, "byurl", "https://example.com/byurl.json");
        let generated = user_manifest(&session, "generated");
        mark_isolated(&root, "generated", &generated.display().to_string());

        let doc = build_export(&session, false).unwrap();
        assert_eq!(
            entry_for(&doc, "byurl")["Source"],
            "https://example.com/byurl.json"
        );
        assert_eq!(
            entry_for(&doc, "generated")["Source"],
            AUTO_GENERATED_SOURCE
        );

        let _ = std::fs::remove_dir_all(&root);
    }

    /// Both scopes are exported: a global install keeps its own root and is
    /// marked in `Info` (upstream `scoop-list.ps1:15-18`) and in the extension.
    #[test]
    fn global_install_is_exported() {
        let root = tmpdir("export_global");
        // A dedicated global root so the test never touches the machine's.
        let global_root = root.join("global");
        let config_path = root.join("hok.json");
        std::fs::write(
            &config_path,
            serde_json::json!({
                "root_path": root.to_string_lossy(),
                "global_path": global_root.to_string_lossy(),
                "cache_path": root.join("cache").to_string_lossy(),
            })
            .to_string(),
        )
        .unwrap();
        let session = crate::Session::new_with(&config_path).unwrap();

        write_bucket_manifest(&root, "main", "local-app", MANIFEST);
        mark_installed(&root, "local-app", "main", MANIFEST, false);
        mark_installed(&global_root, "global-app", "main", MANIFEST, false);

        let doc = build_export(&session, true).unwrap();
        let apps = doc["apps"].as_array().unwrap();
        assert_eq!(apps.len(), 2, "both scopes must be exported: {doc}");

        let local = entry_for(&doc, "local-app");
        assert_eq!(local["Info"], "");
        assert_eq!(local["Hok"]["Global"], false);

        let global = entry_for(&doc, "global-app");
        assert_eq!(global["Info"], INFO_GLOBAL);
        assert_eq!(global["Hok"]["Global"], true);

        let _ = std::fs::remove_dir_all(&root);
    }
}
